/* Boplo Flight — original practice questions for private pilot theory.
   Written for Boplo, based on ICAO-level knowledge common to UK CAA, EASA, FAA and other systems.
   STATUS: draft, pending review by a qualified flight instructor. Do not present as an official question bank.
   Format: [id, subject, question, [options], correctIndex, explanation] */
window.BOPLO_QUESTIONS = (() => {
  const status = 'draft';
  const reviewed = null; // set to {by:'Name, FI(A)', date:'YYYY-MM-DD'} once an instructor has reviewed
  const subjects = [
    ['airlaw', 'Air law', 'Rules of the air, right of way, signals and transponder codes.'],
    ['human', 'Human performance', 'How the body and mind behave in flight, and the traps to avoid.'],
    ['met', 'Meteorology', 'Fog, fronts, icing, pressure and reading weather reports.'],
    ['comms', 'Communications', 'Radio phraseology, readbacks and emergency calls.'],
    ['pof', 'Principles of flight', 'Lift, stalls, turns, flaps and stability.'],
    ['ops', 'Operational procedures', 'Wake turbulence, wind shear and safe operating habits.'],
    ['perf', 'Performance and planning', 'Density altitude, mass and balance, wind components.'],
    ['agk', 'Aircraft general knowledge', 'Engine, carburettor, magnetos, instruments and systems.'],
    ['nav', 'Navigation', 'Variation, the 1 in 60 rule, time, speed and distance.']
  ];
  const Q = [
    // Air law
    ['al1', 'airlaw', 'Which transponder code tells air traffic services you have an emergency?', ['7000', '7500', '7600', '7700'], 3, '7700 is the emergency code. 7600 is radio failure and 7500 is unlawful interference.'],
    ['al2', 'airlaw', 'Two aircraft are converging at about the same level. Which one gives way?', ['The faster aircraft', 'The one that has the other on its right', 'The one that has the other on its left', 'The higher aircraft'], 1, 'The aircraft that has the other on its right gives way, normally by turning right.'],
    ['al3', 'airlaw', 'Two aircraft are approaching head-on. What should each pilot do?', ['Climb', 'Descend', 'Alter heading to the right', 'Alter heading to the left'], 2, 'Both alter heading to the right so they pass left side to left side.'],
    ['al4', 'airlaw', 'You are overtaking another aircraft in flight. How should you pass?', ['Pass on its left', 'Pass on its right, keeping clear', 'Pass directly above it', 'It must move aside for you'], 1, 'The overtaking aircraft keeps out of the way and passes by altering heading to the right.'],
    ['al5', 'airlaw', 'In flight you see a steady red light from the tower aimed at you. What does it mean?', ['Cleared to land', 'Aerodrome unsafe, do not land', 'Give way to other aircraft and continue circling', 'Return to the aerodrome and land'], 2, 'Steady red in flight means give way and keep circling. Flashing red means the aerodrome is unsafe, do not land.'],
    ['al6', 'airlaw', 'On the ground you see a flashing green light from the tower. What does it mean?', ['Cleared for take-off', 'Cleared to taxi', 'Stop', 'Return to the starting point'], 1, 'Flashing green on the ground means cleared to taxi. Steady green means cleared for take-off.'],
    ['al7', 'airlaw', 'A powered aeroplane and a glider are converging. Which normally gives way?', ['The glider', 'The powered aeroplane', 'Whichever is lower', 'Whichever is faster'], 1, 'Powered aircraft give way to gliders, balloons and airships, which are less able to manoeuvre.'],
    ['al8', 'airlaw', 'On the ground you see a flashing white light from the tower. What should you do?', ['Taxi clear of the landing area', 'Return to the starting point on the aerodrome', 'Hold position', 'Continue to the runway'], 1, 'Flashing white to an aircraft on the ground means return to the starting point on the aerodrome.'],
    // Human performance
    ['hp1', 'human', 'Why is hypoxia particularly dangerous?', ['It always causes pain first', 'Its early effects can go unnoticed while judgement is impaired', 'It only affects older pilots', 'It only happens above 25,000 ft'], 1, 'Hypoxia is insidious. Euphoria and impaired judgement can set in before you recognise anything is wrong.'],
    ['hp2', 'human', 'You smell exhaust fumes and feel a headache while the cabin heater is on. What is the most likely cause and first action?', ['Fatigue; open a window later', 'Carbon monoxide; turn the heater off and open fresh-air vents', 'Hyperventilation; breathe faster', 'Fuel vapour; increase power'], 1, 'Cabin heaters often use heat from around the exhaust, so a leak can bring in carbon monoxide. Turn the heat off and get fresh air.'],
    ['hp3', 'human', 'After a long, gentle turn you roll wings level and feel you are now turning the other way. What is this?', ['Hypoxia', 'The leans, a vestibular illusion', 'Carbon monoxide poisoning', 'Normal and safe to follow'], 1, 'The inner ear adapts to a steady turn, so rolling level can feel like a turn the other way. Trust the instruments and the horizon.'],
    ['hp4', 'human', 'Another aircraft on a collision course with you will usually appear to…', ['Move quickly across the windscreen', 'Stay in the same place on the windscreen while growing larger', 'Shrink and then vanish', 'Flash brightly'], 1, 'An object with no relative movement that grows in size is on a collision course. Act early.'],
    ['hp5', 'human', 'What is an effective way to scan for traffic?', ['One continuous sweep', 'Short, regularly spaced eye movements, pausing on each section', 'Staring straight ahead', 'Only looking where ATC says'], 1, 'Eyes detect objects best when stationary, so scan in short steps and pause briefly on each part of the sky.'],
    ['hp6', 'human', 'In cloud you feel strongly that you are climbing, but the instruments show level flight. What should you do?', ['Follow your feeling', 'Believe the instruments', 'Close your eyes to reset', 'Turn back immediately on feel'], 1, 'Your body’s motion senses are unreliable without visual references. Trust the instruments.'],
    ['hp7', 'human', 'Tingling fingers, dizziness and rapid breathing during a stressful moment most likely suggest…', ['Carbon monoxide poisoning', 'Hyperventilation', 'Dehydration only', 'Engine failure'], 1, 'Hyperventilation lowers carbon dioxide in the blood. Slow your breathing deliberately, for example by talking.'],
    ['hp8', 'human', 'Why should pilots not fly soon after scuba diving?', ['Ear wax builds up', 'Reduced cabin pressure raises the risk of decompression sickness', 'It causes colour blindness', 'There is no reason'], 1, 'Nitrogen absorbed while diving can form bubbles at the lower pressure of altitude. Follow the recommended waiting time.'],
    // Meteorology
    ['me1', 'met', 'Which conditions most favour radiation fog?', ['Strong wind and cloud cover', 'Clear night, light wind and moist air', 'Warm air over a cold sea', 'A passing cold front'], 1, 'Clear skies let the ground cool overnight; a light wind and moist air let fog form over land.'],
    ['me2', 'met', 'Advection fog forms when…', ['Air cools on a clear night with no wind', 'Warm, moist air moves over a colder surface', 'Air rises up a mountain slope', 'Rain falls into dry air'], 1, 'Advection fog comes from moist air being cooled from below as it moves over a cold surface, and it can persist in wind.'],
    ['me3', 'met', 'Carburettor icing is most likely when…', ['It is very cold and dry', 'Humidity is high and the engine is at low power', 'Only below −20 °C', 'Only in cloud'], 1, 'Carb icing can occur in warm, humid air well above freezing, and it is most likely at low power, such as in a descent.'],
    ['me4', 'met', 'What are ISA conditions at mean sea level?', ['10 °C and 1013 hPa', '15 °C and 1013.25 hPa', '15 °C and 1000 hPa', '20 °C and 1013.25 hPa'], 1, 'The International Standard Atmosphere uses 15 °C and 1013.25 hPa at sea level, cooling about 2 °C per 1,000 ft.'],
    ['me5', 'met', 'In a METAR, “BKN” cloud cover means…', ['1–2 oktas', '3–4 oktas', '5–7 oktas', '8 oktas'], 2, 'FEW is 1–2 oktas, SCT 3–4, BKN 5–7 and OVC 8.'],
    ['me6', 'met', 'Which of these is part of “CAVOK”?', ['Visibility 5 km or more', 'Visibility 10 km or more and no cloud below 5,000 ft or minimum sector altitude, if higher', 'No wind', 'Cloud base above 1,500 ft'], 1, 'CAVOK means visibility 10 km or more, no cloud below 5,000 ft (or MSA if higher), no cumulonimbus or towering cumulus, and no significant weather.'],
    ['me7', 'met', 'In the northern hemisphere, standing with your back to the wind, low pressure is…', ['On your right', 'On your left', 'Ahead', 'Behind'], 1, 'Buys Ballot’s law: in the northern hemisphere, with your back to the wind, low pressure is on your left.'],
    ['me8', 'met', 'The temperature and dew point in reports are getting closer together. What should you expect?', ['Improving visibility', 'A higher risk of fog or low cloud', 'Stronger winds', 'Thunderstorms only'], 1, 'As air cools towards its dew point it nears saturation, so mist, fog or low cloud become more likely.'],
    ['me9', 'met', 'As a cold front passes in the northern hemisphere, the wind typically…', ['Backs', 'Veers', 'Stops completely', 'Reverses'], 1, 'Wind usually veers (shifts clockwise) as a cold front passes in the northern hemisphere, often with showers and falling temperature.'],
    // Communications
    ['co1', 'comms', 'What does “WILCO” mean?', ['Repeat your message', 'I understand your message and will comply', 'Yes', 'Wait'], 1, 'WILCO means “will comply”. ROGER only means you received the message.'],
    ['co2', 'comms', 'What does “ROGER” mean?', ['I will comply', 'I have received all of your last transmission', 'Yes', 'Say again'], 1, 'ROGER acknowledges receipt only. It is not a readback or an agreement to comply.'],
    ['co3', 'comms', 'Which call signals grave and imminent danger requiring immediate assistance?', ['PAN PAN', 'MAYDAY', 'SECURITE', 'BREAK BREAK'], 1, 'MAYDAY is the distress call. PAN PAN is the urgency call for a serious situation that does not need immediate assistance.'],
    ['co4', 'comms', 'Which of these must you read back to ATC?', ['The weather at another airfield', 'An altimeter (QNH) setting', 'A traffic advisory', 'A frequency you will not use'], 1, 'Altimeter settings, runway instructions, headings, levels, SSR codes and frequency changes must be read back.'],
    ['co5', 'comms', 'Which international distress frequency is monitored for aircraft emergencies?', ['118.0 MHz', '121.5 MHz', '123.45 MHz', '135.0 MHz'], 1, '121.5 MHz is the international aeronautical emergency frequency.'],
    ['co6', 'comms', 'Which word means “yes” in standard radio phraseology?', ['Affirmative', 'Affirm', 'Correct', 'Roger'], 1, 'ICAO phraseology uses AFFIRM for yes and NEGATIVE for no.'],
    ['co7', 'comms', 'Your radio fails. Which transponder code should you select?', ['7000', '7500', '7600', '7700'], 2, '7600 tells ATC you have lost radio communication.'],
    // Principles of flight
    ['pf1', 'pof', 'A wing stalls when…', ['Airspeed falls below a fixed value', 'It exceeds its critical angle of attack', 'The engine stops', 'The nose is above the horizon'], 1, 'A stall happens at the critical angle of attack, which can be reached at any airspeed or attitude.'],
    ['pf2', 'pof', 'In a level 60° banked turn, what is the load factor?', ['1 g', '1.5 g', '2 g', '3 g'], 2, 'Load factor in a level turn is 1 ÷ cos(bank). At 60° that is 2 g, and stall speed rises by about 41%.'],
    ['pf3', 'pof', 'Lowering flap generally…', ['Reduces lift and drag', 'Increases lift and drag and lowers the stall speed', 'Only increases speed', 'Has no effect on stall speed'], 1, 'Flap increases the wing’s lift and drag, letting you fly slower with a steeper approach.'],
    ['pf4', 'pof', 'What is the main purpose of a trim tab?', ['To turn the aircraft', 'To relieve control pressure so the aircraft holds an attitude', 'To lower the stall speed', 'To steer on the ground'], 1, 'Trim removes the need to hold a constant force on the controls.'],
    ['pf5', 'pof', 'How does a centre of gravity near the aft limit affect handling?', ['More stable and heavier controls', 'Less stable, lighter elevator forces and harder stall recovery', 'No change', 'Higher stall speed only'], 1, 'An aft CG reduces longitudinal stability and can make stall and spin recovery more difficult. Never fly outside the limits.'],
    ['pf6', 'pof', 'Close to the ground the aircraft “floats” on landing. Why?', ['Ground effect reduces induced drag', 'The engine produces more power', 'Air is denser at ground level only', 'The flaps retract'], 0, 'Within about one wingspan of the ground, ground effect reduces induced drag, so excess speed makes the aircraft float.'],
    ['pf7', 'pof', 'Rolling into a turn, the nose briefly yaws away from the turn. What causes this?', ['Torque', 'Adverse yaw from extra drag on the rising wing’s aileron', 'Ground effect', 'Weathercocking'], 1, 'The down-going aileron on the rising wing creates more drag, yawing the nose away. Use coordinated rudder.'],
    // Operational procedures
    ['op1', 'ops', 'Wake turbulence is strongest behind an aircraft that is…', ['Light, fast and with flaps down', 'Heavy, slow and clean', 'Light and climbing', 'Taxiing slowly'], 1, 'Heavy, slow, clean aircraft produce the strongest wingtip vortices.'],
    ['op2', 'ops', 'Landing behind a large aircraft that has just landed, how can you avoid its wake?', ['Stay below its approach path and land short of its touchdown point', 'Stay above its approach path and land beyond its touchdown point', 'Land exactly on its touchdown point', 'Approach faster than normal'], 1, 'Vortices sink behind the aircraft and stop when it touches down, so stay above its path and land beyond where it touched down.'],
    ['op3', 'ops', 'A light crosswind on the runway can make wake turbulence more hazardous because…', ['It blows vortices away instantly', 'It can hold one vortex over the runway', 'It strengthens the vortices', 'It has no effect'], 1, 'A light crosswind can keep the upwind vortex stationary over the runway for longer.'],
    ['op4', 'ops', 'On final approach your airspeed suddenly rises then drops sharply. This most likely indicates…', ['Normal gusts only', 'Wind shear', 'A blocked pitot tube', 'Carburettor icing'], 1, 'Sudden airspeed changes on approach suggest wind shear. Be ready to go around.'],
    ['op5', 'ops', 'Taking off after a large aircraft has departed, how should you avoid its wake?', ['Lift off before its rotation point and climb above its path', 'Lift off after its rotation point and stay below its path', 'Follow directly behind and below', 'Take off immediately behind it'], 0, 'Its vortices start where it rotated, so lift off earlier and climb above its flight path, or wait.'],
    // Performance and planning
    ['pe1', 'perf', 'On a hot day at a high-elevation airfield, what should you expect?', ['Shorter take-off run', 'Longer take-off run and poorer climb', 'Better engine performance', 'Lower true airspeed'], 1, 'High density altitude reduces engine, propeller and wing performance.'],
    ['pe2', 'perf', 'Which combination gives the highest density altitude?', ['Cold, high pressure, low elevation', 'Hot, low pressure, high elevation', 'Cold, low pressure, sea level', 'Hot, high pressure, sea level'], 1, 'Heat, low pressure and high elevation all reduce air density. Humidity reduces it a little further.'],
    ['pe3', 'perf', 'Which surface increases take-off distance compared with a dry, level, paved runway?', ['A downhill slope', 'Long wet grass', 'A headwind', 'Lower aircraft mass'], 1, 'Wet or long grass, uphill slopes, tailwinds and higher mass all increase take-off distance.'],
    ['pe4', 'perf', 'How is the centre of gravity position found?', ['Total mass ÷ total moment', 'Total moment ÷ total mass', 'Total mass × total arm', 'Average of all arms'], 1, 'CG arm = total moment ÷ total mass.'],
    ['pe5', 'perf', 'The wind is 20 kt at 30° to the runway. What is the approximate headwind component?', ['10 kt', '14 kt', '17 kt', '20 kt'], 2, 'Headwind ≈ 20 × cos 30° ≈ 17 kt. The crosswind component is 20 × sin 30° = 10 kt.'],
    ['pe6', 'perf', 'A pilot of 80 kg sits at an arm of 2.0 m from the datum. What is the moment?', ['40 kg·m', '82 kg·m', '160 kg·m', '1,600 kg·m'], 2, 'Moment = mass × arm = 80 × 2.0 = 160 kg·m.'],
    ['pe7', 'perf', 'What does a tailwind do to landing distance?', ['Shortens it', 'Lengthens it', 'No effect', 'Only affects take-off'], 1, 'A tailwind increases groundspeed at touchdown and lengthens the landing distance.'],
    ['pe8', 'perf', 'Flying above maximum take-off mass would…', ['Lower the stall speed', 'Raise the stall speed, lengthen take-off and reduce climb', 'Improve stability', 'Have no effect if the runway is long'], 1, 'Excess mass degrades almost every aspect of performance and may exceed structural limits.'],
    // Aircraft general knowledge
    ['ag1', 'agk', 'Applying carburettor heat with no ice present usually causes…', ['An RPM rise', 'A small RPM drop', 'No change', 'Engine failure'], 1, 'Warmer, less dense air richens the mixture and lowers power slightly. If ice is present, RPM may drop and then rise as it melts.'],
    ['ag2', 'agk', 'Why do piston aero engines have two magnetos?', ['To double the power', 'For redundancy and more complete combustion', 'To charge the battery', 'To start the engine only'], 1, 'Each magneto fires its own set of plugs independently, so the engine keeps running if one fails.'],
    ['ag3', 'agk', 'If the static source becomes blocked in flight, the altimeter will…', ['Read too high', 'Read too low', 'Freeze at the level where the blockage happened', 'Work normally'], 2, 'With no change in static pressure, the altimeter freezes. The VSI shows zero and the ASI becomes inaccurate as altitude changes.'],
    ['ag4', 'agk', 'Why is the mixture leaned as you climb?', ['To cool the engine', 'Because air density drops, so less fuel is needed for the correct ratio', 'To increase noise', 'It is never leaned'], 1, 'Thinner air at altitude needs less fuel to keep the correct fuel-to-air ratio.'],
    ['ag5', 'agk', 'In many light aircraft, which instruments are driven by the vacuum system?', ['Airspeed indicator and altimeter', 'Attitude indicator and heading indicator', 'Turn coordinator only', 'Compass and clock'], 1, 'The attitude and heading indicators are commonly vacuum-driven; the turn coordinator is often electric. Check your aircraft’s manual.'],
    ['ag6', 'agk', 'Why must the heading indicator be checked against the magnetic compass regularly?', ['It runs on fuel', 'It drifts over time because of gyroscopic precession', 'It only works on the ground', 'It shows true heading'], 1, 'The heading indicator has no magnetic sensing and drifts, so realign it with the compass in steady flight.'],
    ['ag7', 'agk', 'Which is a likely cause of high oil temperature in the climb?', ['Too rich a mixture', 'Low airspeed and high power for a long time', 'Cold weather', 'A full oil sump'], 1, 'High power with low cooling airflow raises temperatures. A lean mixture or low oil level can also cause it.'],
    // Navigation
    ['na1', 'nav', 'Using the 1 in 60 rule, if you are 1 NM off track after 60 NM, your track error is about…', ['0.5°', '1°', '6°', '60°'], 1, 'The 1 in 60 rule: 1 NM off track in 60 NM is about 1° of error.'],
    ['na2', 'nav', 'What is magnetic variation?', ['The error caused by the aircraft’s own metal', 'The angle between true north and magnetic north', 'The difference between heading and track', 'A change in compass reading in turns'], 1, 'Variation is the angle between true and magnetic north, and it changes with location and time.'],
    ['na3', 'nav', 'True track is 090° and variation is 3° W. What is the magnetic track?', ['087°', '090°', '093°', '270°'], 2, '“Variation west, magnetic best”: add westerly variation, so 090 + 3 = 093°M.'],
    ['na4', 'nav', 'At a groundspeed of 120 kt, how long does it take to fly 30 NM?', ['10 minutes', '15 minutes', '20 minutes', '25 minutes'], 1, '120 kt is 2 NM per minute, so 30 NM takes 15 minutes.'],
    ['na5', 'nav', 'How many metres are there in one nautical mile?', ['1,000 m', '1,609 m', '1,852 m', '2,000 m'], 2, 'One nautical mile is 1,852 m, equal to one minute of latitude.'],
    ['na6', 'nav', 'Compass deviation is caused by…', ['The Earth’s magnetic field changing', 'Magnetic fields in the aircraft itself', 'Wind', 'Altitude'], 1, 'Deviation comes from the aircraft’s own metal and electrics, and is shown on the compass deviation card.'],
    ['na7', 'nav', 'The wind is blowing from your left across your track. To stay on track you should…', ['Head slightly right of track', 'Head slightly left of track, into the wind', 'Fly the track as heading', 'Climb'], 1, 'Turn the nose into the wind to offset drift. With wind from the left, head left of track.'],
    ['na8', 'nav', 'A VOR radial is…', ['A true bearing to the station', 'A magnetic bearing from the station', 'A distance from the station', 'A track to the station'], 1, 'A radial is the magnetic bearing outbound from the VOR station.']
  ];
  const questions = Q.map(([id, subject, q, options, answer, explain]) => ({ id, subject, q, options, answer, explain }));
  const passMark = regime => regime === 'faa' ? 70 : 75; // FAA knowledge tests 70%; UK/EASA theory papers 75%
  return { status, reviewed, subjects: subjects.map(([id, name, blurb]) => ({ id, name, blurb, count: questions.filter(x => x.subject === id).length })), questions, passMark };
})();
